<?php defined('ABSPATH') || exit;$base=home_url('/companion/');$root='dungeon-master/campaigns/'.$campaign->id().'/evidence';$active=array_values(array_filter($records??[],static fn($r):bool=>!$r->isArchived()));$archived=array_values(array_filter($records??[],static fn($r):bool=>$r->isArchived()));$threads=array_values(array_filter($active,static fn($r):bool=>$r->isThread()));$evidence=array_values(array_filter($active,static fn($r):bool=>!$r->isThread())); ?>
<section class="gmrc-evidence" aria-labelledby="gmrc-evidence-title"><header class="gmrc-evidence__hero"><div><p class="gmrc-dm-desk__eyebrow">Keeper’s Workshop · Evidence Register</p><h1 id="gmrc-evidence-title">The Evidence Register</h1><p>Preserve the clues, secrets and unanswered questions of <strong><?php echo esc_html($campaign->name()); ?></strong> before they become pins and string.</p></div><?php if(!$campaign->isArchived()): ?><a class="gmrc-evidence-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/create',$base)); ?>">Record Evidence or Thread</a><?php endif; ?></header><?php if(($flash['success']??null)): ?><p class="gmrc-evidence-flash" role="status"><?php echo esc_html($flash['success']); ?></p><?php endif; ?>
