<?php if($active===[]): ?><article class="gmrc-evidence-empty"><div aria-hidden="true">🔎</div><h2>The first clue has not surfaced yet</h2><p>Record evidence, rumours, secrets and open questions. The future Conspiracy Board will arrange these records without becoming their source of truth.</p></article><?php else: ?><?php if($threads!==[]): ?><h2 class="gmrc-evidence-heading">Open Threads</h2><div class="gmrc-evidence-grid"><?php foreach($threads as $record): ?><article class="gmrc-evidence-card gmrc-evidence-card--thread"><div class="gmrc-evidence-card__meta"><span>Thread</span><span><?php echo $record->isKeeperOnly()?'🔒 Keeper only':'◉ Player-visible'; ?></span></div><h3><?php echo esc_html($record->name()); ?></h3><p><?php echo esc_html($record->summary()!==''?$record->summary():'No question or summary has been written yet.'); ?></p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$record->id(),$base)); ?>">Follow thread →</a></article><?php endforeach; ?></div><?php endif; ?><?php if($evidence!==[]): ?><h2 class="gmrc-evidence-heading">Evidence</h2><div class="gmrc-evidence-grid"><?php foreach($evidence as $record): ?><article class="gmrc-evidence-card"><div class="gmrc-evidence-card__meta"><span><?php echo esc_html($record->typeLabel()); ?></span><span><?php echo $record->isKeeperOnly()?'🔒 Keeper only':'◉ Player-visible'; ?></span></div><h3><?php echo esc_html($record->name()); ?></h3><p><?php echo esc_html($record->summary()!==''?$record->summary():'No at-a-glance description has been written yet.'); ?></p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$record->id(),$base)); ?>">Open evidence →</a></article><?php endforeach; ?></div><?php endif; ?><?php endif; ?>
<?php if($archived!==[]): ?><details class="gmrc-evidence-archive"><summary>Archived records (<?php echo count($archived); ?>)</summary><div class="gmrc-evidence-grid"><?php foreach($archived as $record): ?><article class="gmrc-evidence-card"><h3><?php echo esc_html($record->name()); ?></h3><p><?php echo esc_html($record->typeLabel()); ?> · Archived</p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$record->id(),$base)); ?>">Read archived record</a></article><?php endforeach; ?></div></details><?php endif; ?><p class="gmrc-evidence-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route','dungeon-master/campaigns/'.$campaign->id(),$base)); ?>">← Back to Campaign Command Centre</a></p></section>
